window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["clickhouse"]={html:"<div class=\"own-clickhouse\">\n  <header class=\"nav\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"Northwind home\">\n      <span class=\"brand-mark\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"4\" y=\"14\" width=\"4\" height=\"6\" rx=\"1\"/><rect x=\"10\" y=\"9\" width=\"4\" height=\"11\" rx=\"1\"/><rect x=\"16\" y=\"4\" width=\"4\" height=\"16\" rx=\"1\"/></svg></span>\n      Northwind\n    </a>\n    <nav class=\"nav-links\" aria-label=\"Primary\">\n      <a href=\"#product\">Product</a>\n      <a href=\"#usecases\">Use cases</a>\n      <a href=\"#pricing\">Pricing</a>\n      <a href=\"#resources\">Resources</a>\n      <a href=\"#customers\">Customers</a>\n    </nav>\n    <div class=\"nav-right\">\n      <a class=\"nav-signin\" href=\"#\">Sign in</a>\n      <a class=\"btn btn-primary\" href=\"#\">Get Started</a>\n    </div>\n  </header>\n\n  <section class=\"hero\" id=\"top\" aria-labelledby=\"heroH\">\n    <div class=\"wrap hero-grid\">\n      <div class=\"hero-copy\">\n        <span class=\"badge-yellow\">New · Vectorized ingest v3</span>\n        <h1 id=\"heroH\">The leading operations database for realtime teams</h1>\n        <p class=\"lead\">Sub-second analytics over billions of events. Northwind keeps your whole operations grid queryable in the blink of an eye.</p>\n        <div class=\"hero-actions\">\n          <a class=\"btn btn-primary\" href=\"#\">Get started free</a>\n          <a class=\"btn btn-secondary\" href=\"#product\">View the docs</a>\n        </div>\n        <div class=\"hero-stats\">\n          <div class=\"hstat\"><b>779+</b><span>contributors</span></div>\n          <div class=\"hstat\"><b>2.8k+</b><span>deployments</span></div>\n          <div class=\"hstat\"><b>47k+</b><span>stars</span></div>\n        </div>\n      </div>\n      <div class=\"code-window\" aria-hidden=\"true\">\n        <div class=\"code-bar\"><span class=\"cdot r\"></span><span class=\"cdot y\"></span><span class=\"cdot g\"></span><span class=\"code-file\">throughput.sql</span></div>\n        <pre class=\"code-body\"><span class=\"ln\">1</span><span class=\"kw\">SELECT</span> region,\n<span class=\"ln\">2</span>       <span class=\"fn\">round</span>(<span class=\"fn\">avg</span>(events_per_min)) <span class=\"kw\">AS</span> avg_throughput\n<span class=\"ln\">3</span><span class=\"kw\">FROM</span> ops.telemetry\n<span class=\"ln\">4</span><span class=\"kw\">WHERE</span> ts &gt;= now() - <span class=\"kw\">INTERVAL</span> <span class=\"st\">1</span> <span class=\"kw\">HOUR</span>\n<span class=\"ln\">5</span><span class=\"kw\">GROUP BY</span> region\n<span class=\"ln\">6</span><span class=\"kw\">ORDER BY</span> avg_throughput <span class=\"kw\">DESC</span>\n<span class=\"ln\">7</span><span class=\"kw\">FORMAT</span> PrettyCompact;</pre>\n        <div class=\"code-status\"><span class=\"ok-dot\"></span>6 rows in set. Elapsed: 0.042 sec.</div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"challenges\" id=\"product\" aria-labelledby=\"chalH\">\n    <div class=\"wrap\">\n      <h2 id=\"chalH\" class=\"display-lg\">Built for every modern operations challenge</h2>\n      <div class=\"challenge-grid\">\n        <article class=\"challenge\">\n          <span class=\"cicon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M13 2 4 14h6l-1 8 9-12h-6z\"/></svg></span>\n          <h3>Realtime streaming</h3>\n          <p>Millions of events per second, queryable the instant they land.</p>\n        </article>\n        <article class=\"challenge\">\n          <span class=\"cicon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M12 7v5l3 3\"/></svg></span>\n          <h3>Sub-second queries</h3>\n          <p>Columnar, vectorized execution that answers before you blink.</p>\n        </article>\n        <article class=\"challenge\">\n          <span class=\"cicon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"16\" rx=\"2\"/><path d=\"M3 9h18M8 4v16\"/></svg></span>\n          <h3>SQL-native</h3>\n          <p>Full SQL with window, join and approximate functions out of the box.</p>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"usecases\" id=\"usecases\" aria-labelledby=\"useH\">\n    <div class=\"wrap use-grid\">\n      <div class=\"use-copy\">\n        <p class=\"caption-upper\">Use cases</p>\n        <h2 id=\"useH\" class=\"display-lg\">Show the query, not an illustration of it</h2>\n        <p class=\"lead\">Northwind is a database — so the marketing shows real queries, real plans, real latency. Paste a query, get a dashboard back.</p>\n        <ul class=\"check-list\">\n          <li>Observability over every region</li>\n          <li>Realtime operations dashboards</li>\n          <li>Anomaly detection at ingest scale</li>\n        </ul>\n        <a class=\"btn btn-secondary\" href=\"#\">Explore use cases</a>\n      </div>\n      <div class=\"mock-card\" aria-hidden=\"true\">\n        <div class=\"mock-head\"><span>Query latency · p50</span><b>0.42s</b></div>\n        <div class=\"bars\"><span style=\"--h:44%\"></span><span style=\"--h:62%\"></span><span style=\"--h:38%\"></span><span style=\"--h:78%\"></span><span style=\"--h:52%\"></span><span style=\"--h:88%\"></span><span style=\"--h:66%\"></span><span style=\"--h:96%\"></span></div>\n        <div class=\"mock-foot\"><span>APAC</span><span>EMEA</span><span>AMER</span><span>LATAM</span></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"customers\" id=\"customers\" aria-label=\"Customers\">\n    <div class=\"wrap\">\n      <p class=\"caption-upper center\">Trusted by operations teams everywhere</p>\n      <div class=\"logo-strip\" aria-label=\"Customer logos (fictional)\">\n        <span>Northline</span><span>Gridwise</span><span>Fathom</span><span>Meridian</span><span>Lumen</span><span>Orbit</span>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"events\" aria-labelledby=\"eventsH\">\n    <div class=\"wrap\">\n      <div class=\"head-row\">\n        <h2 id=\"eventsH\" class=\"display-md\">Upcoming events</h2>\n        <a class=\"tlink\" href=\"#\">All events &rarr;</a>\n      </div>\n      <div class=\"event-grid\">\n        <article class=\"event-card\">\n          <p class=\"caption-upper\">19 NOVEMBER 2026</p>\n          <h3 class=\"event-title\">Realtime ops meetup · Singapore</h3>\n          <p class=\"event-meta\">In person · Free</p>\n          <a class=\"tlink\" href=\"#\">Register &rarr;</a>\n        </article>\n        <article class=\"event-card\">\n          <p class=\"caption-upper\">02 DECEMBER 2026</p>\n          <h3 class=\"event-title\">Webinar: Taming 2M events/min</h3>\n          <p class=\"event-meta\">Online · Free</p>\n          <a class=\"tlink\" href=\"#\">Register &rarr;</a>\n        </article>\n        <article class=\"event-card\">\n          <p class=\"caption-upper\">14 JANUARY 2027</p>\n          <h3 class=\"event-title\">Northwind user conference</h3>\n          <p class=\"event-meta\">In person · Ticketed</p>\n          <a class=\"tlink\" href=\"#\">Register &rarr;</a>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"pricing\" id=\"pricing\" aria-labelledby=\"priceH\">\n    <div class=\"wrap\">\n      <h2 id=\"priceH\" class=\"display-lg center\">Pricing that scales with your grid</h2>\n      <div class=\"pricing-grid\">\n        <article class=\"tier\">\n          <h3 class=\"tier-name\">Free</h3>\n          <p class=\"tier-price\">$0</p>\n          <ul class=\"check-list\"><li>1 region</li><li>7-day retention</li><li>Community support</li></ul>\n          <a class=\"btn btn-secondary\" href=\"#\">Get started</a>\n        </article>\n        <article class=\"tier tier-featured\">\n          <span class=\"badge-yellow\">Featured</span>\n          <h3 class=\"tier-name\">Cloud</h3>\n          <p class=\"tier-price\">$49</p>\n          <ul class=\"check-list\"><li>18 regions</li><li>13-month retention</li><li>Alert routing</li></ul>\n          <a class=\"btn btn-on-yellow\" href=\"#\">Start free</a>\n        </article>\n        <article class=\"tier\">\n          <h3 class=\"tier-name\">Dedicated</h3>\n          <p class=\"tier-price\">Custom</p>\n          <ul class=\"check-list\"><li>41 regions</li><li>36-month retention</li><li>Dedicated crew</li></ul>\n          <a class=\"btn btn-secondary\" href=\"#\">Contact sales</a>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"cta-band\">\n    <div class=\"wrap cta-inner\">\n      <h2 class=\"display-md\">Deploy your way</h2>\n      <p>Run open source, cloud, or dedicated — sub-second analytics everywhere.</p>\n      <a class=\"btn btn-on-yellow btn-lg\" href=\"#\">Get started free</a>\n    </div>\n  </section>\n\n  <footer class=\"foot\">\n    <div class=\"wrap foot-grid\">\n      <div class=\"foot-brand\">\n        <p class=\"foot-word\">Northwind</p>\n        <p class=\"foot-tag\">Realtime operations analytics.</p>\n      </div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Product</p><a href=\"#\">Streaming</a><a href=\"#\">Queries</a><a href=\"#\">Alerts</a><a href=\"#\">Integrations</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Use cases</p><a href=\"#\">Observability</a><a href=\"#\">Dashboards</a><a href=\"#\">Anomalies</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Resources</p><a href=\"#\">Docs</a><a href=\"#\">Events</a><a href=\"#\">Status</a></div>\n      <div class=\"foot-col\"><p class=\"foot-h\">Company</p><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n    </div>\n    <div class=\"wrap foot-bottom\">\n      <p>Northwind is a fictional product. Sample data — showcase only.</p>\n      <span>© 2026 Northwind</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the ClickHouse design language ════════════\n   Scoped under .own-clickhouse. Tokens from design-md/clickhouse/DESIGN.md.\n   Near-pure black canvas with electric-yellow brand voltage, white Inter at\n   weight 700 for display (tight negative tracking), dark surface cards barely\n   lighter than canvas, SQL code windows, and yellow stat callouts. */\n\n.own-clickhouse {\n  --canvas: #0a0a0a;\n  --surface-soft: #121212;\n  --surface-card: #1a1a1a;\n  --surface-elevated: #242424;\n  --hairline: #2a2a2a;\n  --hairline-strong: #3a3a3a;\n  --ink: #ffffff;\n  --body: #cccccc;\n  --body-strong: #e6e6e6;\n  --muted: #888888;\n  --muted-soft: #5a5a5a;\n  --primary: #faff69;\n  --primary-active: #e6eb52;\n  --on-primary: #0a0a0a;\n  --on-dark: #ffffff;\n  --accent-emerald: #22c55e;\n  --accent-rose: #ef4444;\n  --accent-blue: #3b82f6;\n\n  --display: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  --body-font: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  --mono: \"JetBrains Mono\", ui-monospace, monospace;\n\n  --gut: clamp(20px, 4.4cqi, 32px);\n  --section: clamp(56px, 8cqi, 96px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--body-font);\n  font-size: 16px;\n  font-weight: 400;\n  line-height: 1.55;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n}\n.own-clickhouse *,\n.own-clickhouse *::before,\n.own-clickhouse *::after { box-sizing: border-box; }\n.own-clickhouse :focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; border-radius: 4px; }\n.own-clickhouse a { color: inherit; text-decoration: none; }\n.own-clickhouse .wrap { max-width: 1280px; margin: 0 auto; padding: 0 var(--gut); }\n.own-clickhouse .center { text-align: center; }\n.own-clickhouse .lead { color: var(--body); font-size: 17px; line-height: 1.55; }\n\n/* ── type ─────────────────────────────────────────────────────────────── */\n.own-clickhouse .display-lg {\n  font-family: var(--display); font-weight: 700;\n  font-size: clamp(32px, 4.6cqi, 56px); line-height: 1.1; letter-spacing: -.035em; margin: 0;\n}\n.own-clickhouse .display-md {\n  font-family: var(--display); font-weight: 700;\n  font-size: clamp(24px, 3cqi, 40px); line-height: 1.15; letter-spacing: -.025em; margin: 0;\n}\n.own-clickhouse .caption-upper {\n  font-family: var(--body-font); font-weight: 600; font-size: 12px; letter-spacing: 1.5px;\n  text-transform: uppercase; color: var(--muted); margin: 0 0 14px;\n}\n\n/* ── buttons / links ─────────────────────────────────────────────────── */\n.own-clickhouse .btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 40px; padding: 0 20px; border-radius: 8px;\n  font-family: var(--body-font); font-weight: 600; font-size: 14px;\n  border: 1px solid transparent; cursor: pointer; white-space: nowrap;\n  transition: background-color .15s ease, color .15s ease, border-color .15s ease, filter .15s ease;\n}\n.own-clickhouse .btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-clickhouse .btn-primary:hover { background: var(--primary-active); }\n.own-clickhouse .btn-secondary { background: var(--surface-card); color: var(--on-dark); }\n.own-clickhouse .btn-secondary:hover { background: var(--surface-elevated); }\n.own-clickhouse .btn-on-yellow { background: var(--canvas); color: var(--ink); }\n.own-clickhouse .btn-lg { height: 44px; padding: 0 26px; font-size: 15px; }\n.own-clickhouse .tlink { color: var(--primary); font-weight: 600; font-size: 14px; }\n.own-clickhouse .tlink:hover { text-decoration: underline; }\n.own-clickhouse .badge-yellow {\n  display: inline-block; background: var(--primary); color: var(--on-primary);\n  font-size: 12px; font-weight: 600; letter-spacing: 1.5px; text-transform: uppercase;\n  padding: 4px 12px; border-radius: 9999px; margin-bottom: 20px;\n}\n\n/* ── nav ──────────────────────────────────────────────────────────────── */\n.own-clickhouse .nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 32px;\n  height: 64px; padding: 0 var(--gut);\n  background: rgba(10,10,10,.9); border-bottom: 1px solid var(--hairline);\n  backdrop-filter: blur(8px);\n}\n.own-clickhouse .brand { display: inline-flex; align-items: center; gap: 10px; font-family: var(--display); font-weight: 700; font-size: 19px; letter-spacing: -.02em; }\n.own-clickhouse .brand-mark { display: inline-grid; place-items: center; width: 26px; height: 26px; border-radius: 6px; background: var(--primary); }\n.own-clickhouse .brand-mark svg { width: 18px; height: 18px; fill: var(--on-primary); }\n.own-clickhouse .nav-links { display: flex; align-items: center; gap: 26px; }\n.own-clickhouse .nav-links a { font-size: 14px; font-weight: 500; color: var(--body); }\n.own-clickhouse .nav-links a:hover { color: var(--on-dark); }\n.own-clickhouse .nav-right { margin-left: auto; display: flex; align-items: center; gap: 16px; }\n.own-clickhouse .nav-signin { font-size: 14px; font-weight: 500; color: var(--body); }\n\n/* ── hero ─────────────────────────────────────────────────────────────── */\n.own-clickhouse .hero { padding: var(--section) 0; }\n.own-clickhouse .hero-grid { display: grid; grid-template-columns: 7fr 5fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-clickhouse .hero h1 {\n  font-family: var(--display); font-weight: 700;\n  font-size: clamp(38px, 5.6cqi, 72px); line-height: 1.05; letter-spacing: -.04em; margin: 0 0 22px;\n}\n.own-clickhouse .hero-actions { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 30px; }\n.own-clickhouse .hero-stats { display: flex; gap: clamp(24px, 4cqi, 48px); margin-top: 40px; }\n.own-clickhouse .hstat b { display: block; font-family: var(--display); font-weight: 700; font-size: clamp(30px, 3.4cqi, 56px); line-height: 1; letter-spacing: -.03em; color: var(--primary); }\n.own-clickhouse .hstat span { display: block; font-size: 12px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--muted); margin-top: 8px; }\n\n/* ── code window ─────────────────────────────────────────────────────── */\n.own-clickhouse .code-window { background: var(--surface-card); border: 1px solid var(--hairline); border-radius: 12px; padding: 24px; overflow: hidden; }\n.own-clickhouse .code-bar { display: flex; align-items: center; gap: 7px; margin-bottom: 18px; }\n.own-clickhouse .cdot { width: 11px; height: 11px; border-radius: 9999px; }\n.own-clickhouse .cdot.r { background: var(--accent-rose); } .own-clickhouse .cdot.y { background: var(--primary); } .own-clickhouse .cdot.g { background: var(--accent-emerald); }\n.own-clickhouse .code-file { margin-left: 12px; font-family: var(--mono); font-size: 12px; color: var(--muted); }\n.own-clickhouse .code-body { margin: 0; font-family: var(--mono); font-size: 14px; line-height: 1.55; color: var(--on-dark); white-space: pre; overflow-x: auto; }\n.own-clickhouse .code-body .ln { display: inline-block; width: 22px; color: var(--muted-soft); user-select: none; }\n.own-clickhouse .code-body .kw { color: var(--primary); } .own-clickhouse .code-body .fn { color: #7db3ff; } .own-clickhouse .code-body .st { color: #e8b94a; }\n.own-clickhouse .code-status { display: flex; align-items: center; gap: 8px; margin-top: 16px; padding-top: 14px; border-top: 1px solid var(--surface-elevated); font-family: var(--mono); font-size: 12px; color: var(--muted); }\n.own-clickhouse .ok-dot { width: 8px; height: 8px; border-radius: 9999px; background: var(--accent-emerald); }\n\n/* ── challenges ──────────────────────────────────────────────────────── */\n.own-clickhouse .challenges { padding: var(--section) 0; }\n.own-clickhouse .challenges .display-lg { max-width: 700px; margin-bottom: 44px; }\n.own-clickhouse .challenge-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-clickhouse .challenge { background: var(--surface-card); border-radius: 12px; padding: 32px; }\n.own-clickhouse .cicon { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 10px; background: var(--primary); margin-bottom: 20px; }\n.own-clickhouse .cicon svg { width: 22px; height: 22px; fill: none; stroke: var(--on-primary); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-clickhouse .challenge h3 { font-family: var(--body-font); font-weight: 600; font-size: 18px; margin: 0 0 10px; }\n.own-clickhouse .challenge p { color: var(--body); margin: 0; }\n\n/* ── use cases ───────────────────────────────────────────────────────── */\n.own-clickhouse .usecases { padding: var(--section) 0; }\n.own-clickhouse .use-grid { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-clickhouse .use-copy .display-lg { max-width: 13ch; margin-bottom: 18px; }\n.own-clickhouse .check-list { list-style: none; margin: 22px 0; padding: 0; display: grid; gap: 12px; }\n.own-clickhouse .check-list li { position: relative; padding-left: 28px; color: var(--body); }\n.own-clickhouse .check-list li::before { content: \"\"; position: absolute; left: 0; top: 4px; width: 16px; height: 9px; border-left: 2px solid var(--primary); border-bottom: 2px solid var(--primary); transform: rotate(-45deg); }\n.own-clickhouse .mock-card { background: var(--surface-card); border-radius: 12px; padding: 24px; }\n.own-clickhouse .mock-head { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: 20px; font-size: 13px; color: var(--muted); font-weight: 500; }\n.own-clickhouse .mock-head b { font-family: var(--display); font-weight: 700; font-size: 24px; letter-spacing: -.03em; color: var(--primary); }\n.own-clickhouse .bars { display: flex; align-items: flex-end; gap: 10px; height: 110px; }\n.own-clickhouse .bars span { flex: 1; height: var(--h); background: var(--surface-elevated); border-radius: 4px 4px 0 0; }\n.own-clickhouse .bars span:nth-child(4), .own-clickhouse .bars span:nth-child(8) { background: var(--primary); }\n.own-clickhouse .mock-foot { display: flex; justify-content: space-between; margin-top: 14px; font-size: 11px; letter-spacing: .06em; text-transform: uppercase; color: var(--muted); }\n\n/* ── customers ───────────────────────────────────────────────────────── */\n.own-clickhouse .customers { padding: calc(var(--section) / 1.6) 0; }\n.own-clickhouse .logo-strip { display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: clamp(28px, 6cqi, 72px); margin-top: 24px; }\n.own-clickhouse .logo-strip span { font-family: var(--display); font-weight: 700; font-size: clamp(18px, 2cqi, 24px); letter-spacing: -.02em; color: var(--muted); transition: color .2s ease; }\n.own-clickhouse .logo-strip span:hover { color: var(--body-strong); }\n\n/* ── events ──────────────────────────────────────────────────────────── */\n.own-clickhouse .events { padding: var(--section) 0; }\n.own-clickhouse .head-row { display: flex; align-items: baseline; justify-content: space-between; gap: 16px; margin-bottom: 32px; }\n.own-clickhouse .event-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-clickhouse .event-card { background: var(--surface-card); border-radius: 12px; padding: 24px; display: flex; flex-direction: column; gap: 6px; }\n.own-clickhouse .event-title { font-family: var(--body-font); font-weight: 600; font-size: 18px; line-height: 1.3; margin: 4px 0 0; }\n.own-clickhouse .event-meta { color: var(--muted); font-size: 14px; margin: 0 0 12px; }\n.own-clickhouse .event-card .tlink { margin-top: auto; }\n\n/* ── pricing ─────────────────────────────────────────────────────────── */\n.own-clickhouse .pricing { padding: var(--section) 0; }\n.own-clickhouse .pricing .display-lg { margin-bottom: 44px; }\n.own-clickhouse .pricing-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-clickhouse .tier { background: var(--surface-card); border: 1px solid var(--hairline); border-radius: 12px; padding: 32px; display: flex; flex-direction: column; }\n.own-clickhouse .tier-featured { background: var(--primary); border-color: var(--primary); color: var(--on-primary); }\n.own-clickhouse .tier-featured .badge-yellow { background: var(--on-primary); color: var(--primary); }\n.own-clickhouse .tier-name { font-family: var(--body-font); font-weight: 700; font-size: 24px; letter-spacing: -.02em; margin: 0 0 14px; }\n.own-clickhouse .tier-price { font-family: var(--display); font-weight: 700; font-size: 40px; letter-spacing: -.03em; margin: 0 0 20px; }\n.own-clickhouse .tier-featured .check-list li { color: var(--on-primary); }\n.own-clickhouse .tier-featured .check-list li::before { border-color: var(--on-primary); }\n.own-clickhouse .tier .btn { margin-top: auto; }\n.own-clickhouse .tier .check-list { margin-bottom: 24px; }\n\n/* ── CTA band ────────────────────────────────────────────────────────── */\n.own-clickhouse .cta-band { padding: 0 0 var(--section); }\n.own-clickhouse .cta-inner { background: var(--primary); color: var(--on-primary); border-radius: 12px; padding: clamp(40px, 5.5cqi, 64px); text-align: center; display: grid; justify-items: center; gap: 14px; }\n.own-clickhouse .cta-inner p { margin: 0; color: rgba(10,10,10,.78); }\n.own-clickhouse .cta-inner .btn { margin-top: 8px; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-clickhouse .foot { padding: clamp(48px, 6cqi, 64px) 0 28px; border-top: 1px solid var(--hairline); }\n.own-clickhouse .foot-grid { display: grid; grid-template-columns: 1.4fr repeat(4, 1fr); gap: 24px; padding-bottom: 40px; }\n.own-clickhouse .foot-word { font-family: var(--display); font-weight: 700; font-size: 22px; letter-spacing: -.03em; margin: 0 0 10px; }\n.own-clickhouse .foot-tag { font-size: 14px; color: var(--muted); margin: 0; }\n.own-clickhouse .foot-col { display: flex; flex-direction: column; gap: 10px; }\n.own-clickhouse .foot-h { font-size: 13px; font-weight: 600; color: var(--on-dark); margin: 0 0 4px; }\n.own-clickhouse .foot-col a { font-size: 14px; color: var(--muted); }\n.own-clickhouse .foot-col a:hover { color: var(--primary); }\n.own-clickhouse .foot-bottom { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding-top: 22px; border-top: 1px solid var(--hairline); font-size: 13px; color: var(--muted); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-clickhouse .hero-grid, .own-clickhouse .use-grid { grid-template-columns: 1fr; }\n  .own-clickhouse .challenge-grid, .own-clickhouse .event-grid, .own-clickhouse .pricing-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-clickhouse .foot-grid { grid-template-columns: 1.4fr repeat(2, 1fr); }\n}\n@container frame (max-width: 760px) {\n  .own-clickhouse .nav-links, .own-clickhouse .nav-signin { display: none; }\n  .own-clickhouse .challenge-grid, .own-clickhouse .event-grid, .own-clickhouse .pricing-grid { grid-template-columns: 1fr; }\n  .own-clickhouse .hero-stats { flex-wrap: wrap; gap: 20px 32px; }\n  .own-clickhouse .foot-grid { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 430px) {\n  .own-clickhouse .foot-grid { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-clickhouse *, .own-clickhouse *::before, .own-clickhouse *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
